    document.querySelectorAll('[data-reviews-carousel]').forEach(el => { el.dataset.lazyComponent = 'reviews'; lazyObserver.observe(el); });
    document.querySelectorAll('[data-location-carousel]').forEach(el => { el.dataset.lazyComponent = 'location-carousel'; lazyObserver.observe(el); });
    document.querySelectorAll('[data-accordion]').forEach(el => { el.dataset.lazyComponent = 'accordions'; lazyObserver.observe(el); });

    // 3. Idle-load non-critical features
    runIdle(() => {
      initStickyCta();

      // Smooth Scroll
      document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function (e) {
          const target = document.querySelector(this.getAttribute('href'));
          if (target) {
            e.preventDefault();
            target.scrollIntoView({ behavior: 'smooth' });
          }
        });
      });

      // Reveal Color Animation (already observer based in logic)
      const revealObserver = new IntersectionObserver(entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            setTimeout(() => entry.target.classList.remove('grayscale'), 200);
            revealObserver.unobserve(entry.target);
          }
        });
      }, { rootMargin: '-50px', threshold: 0.2 });
      document.querySelectorAll('[data-reveal-color]').forEach(img => revealObserver.observe(img));
    });
  });

})();

/**
 * Map Facade
 * Lazy loads Leaflet and initializes maps on scroll.
 */
document.addEventListener('DOMContentLoaded', function () {
    const mapContainers = document.querySelectorAll('[data-chroma-map]');
    if (!mapContainers.length) return;

    const loadMapAssets = () => {
        // Prevent multiple loads
        if (window.chromaMapAssetsLoaded) return;
        window.chromaMapAssetsLoaded = true;

        // Load Leaflet CSS
        const link = document.createElement('link');
        link.rel = 'stylesheet';
        link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
        document.head.appendChild(link);

        // Load Leaflet JS
        const script = document.createElement('script');
        script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
        script.async = true;
        script.onload = () => {
            // Load Map Layer Logic
            const mapLayerScript = document.createElement('script');
            mapLayerScript.src = chromaData.themeUrl + '/assets/js/map-layer.js';
            mapLayerScript.async = true;
            document.body.appendChild(mapLayerScript);
        };
        document.body.appendChild(script);
    };

    // Intersection Observer
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                loadMapAssets();
                observer.disconnect();
            }
        });
    }, {
        rootMargin: '200px' // Start loading before it comes into view
    });

    mapContainers.forEach(container => observer.observe(container));
});

